from lib import *
S = SS('k33')
F1 = [['limits.memory 64Mi', 'memory.max = 64 MiB'], ['memory.oom.group', '= 1'], ['python 分配 100 MiB', '越过 memory.max'], ['OOMKilled', 'exitCode 137']]
F2 = [['PID 1 = sh', '子进程 python 分配 100 MiB'], ['内核 OOM', 'oom_kill 4 / group_kill 1'], ['整个容器被杀', 'sh 与 sleep 也没了'], ['restartCount', '1']]
F3 = [['写 100 MiB → tmpfs', '计入内存'], ['容器被杀 + 重启', 'tmpfs 数据还在'], ['StartError', 'container init was OOM-killed'], ['写 100 MiB → 磁盘', '页缓存可回收,不超限']]
